    if (copy) {
        return copy(py::arg({keyword.key}) = val) /* CHECKME: keywords ['deep'] */.modify_vertex_labels(n, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val) /* CHECKME: keywords ['a', 'b', 'mu', 'c', 'copy'] */;
    }
    if (n == 0) {
        uncoupled[0] = a;
    } else {
        inner_sectors[n - 1] = a;
    }
    uncoupled[n + 1] = b;
