/// Split into two separate fusion trees.
std::pair<FusionTree, FusionTree> FusionTree::split(int64 n) {
    /* CHECKME: converted from following python code:
     * n = int(n)
     *         if n < 2:
     *             raise ValueError('Left tree has no vertices (n < 2)')
     *         if n >= self.num_uncoupled:
     *             raise ValueError('Right tree has no vertices (n >= num_uncoupled)')
     * cut_sector = self.inner_sectors[n - 2]
     *         t1 = FusionTree(
     *             self.symmetry,
     *             uncoupled=self.uncoupled[:n],
     *             coupled=cut_sector,
     *             are_dual=self.are_dual[:n],
     *             inner_sectors=self.inner_sectors[: n - 2],
     *             multiplicities=self.multiplicities[: n - 1],
     *         )
     *         t2 = FusionTree(
     *             self.symmetry,
     *             uncoupled=concat_sector_arrays(sector_array_from_sector(cut_sector), self.uncoupled[n:]),
     *             coupled=self.coupled,
     *             are_dual=np.insert(self.are_dual[n:], 0, False),
     *             inner_sectors=self.inner_sectors[n - 1 :],
     *             multiplicities=self.multiplicities[n - 1 :],
     *         )
     * return t1, t2
     */
    n = int(n);
    if (n < 2) {
        throw std::invalid_argument("Left tree has no vertices (n < 2)");
    }
    if (n >= num_uncoupled) {
        throw std::invalid_argument("Right tree has no vertices (n >= num_uncoupled)");
    }
    auto /* CHECKME: type? */ cut_sector = inner_sectors[n - 2];
    auto /* CHECKME: type? */ t1 = FusionTree(symmetry, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val) /* CHECKME: keywords ['uncoupled', 'coupled', 'are_dual', 'inner_sectors', 'multiplicities'] */;
    auto /* CHECKME: type? */ t2 = FusionTree(symmetry, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val) /* CHECKME: keywords ['uncoupled', 'coupled', 'are_dual', 'inner_sectors', 'multiplicities'] */;
    return std::make_tuple(t1, t2);
}

/// Split off the bottom vertex.
std::tuple<FusionTree, Sector, int64, Sector> FusionTree::split_bottom_vertex() {
    /* CHECKME: converted from following python code:
     *         if self.num_uncoupled == 0:
     *             raise ValueError('Cant split empty tree')
     *         if self.num_uncoupled == 1:
     *             return FusionTree.from_empty(self.symmetry), self.coupled, 0, self.coupled
     *         if self.num_uncoupled == 2:
     *             rest_tree = FusionTree.from_sector(self.symmetry, self.uncoupled[0], is_dual=self.are_dual[0])
     *             return rest_tree, self.coupled, self.multiplicities[0], self.uncoupled[-1]
     *         rest_tree = FusionTree(
     *             self.symmetry,
     *             uncoupled=self.uncoupled[:-1],
     *             coupled=self.inner_sectors[-1],
     *             are_dual=self.are_dual[:-1],
     *             inner_sectors=self.inner_sectors[:-1],
     *             multiplicities=self.multiplicities[:-1],
     *         )
     * return rest_tree, self.coupled, self.multiplicities[-1], self.uncoupled[-1]
     */
    if (num_uncoupled == 0) {
        throw std::invalid_argument("Cant split empty tree");
    }
    if (num_uncoupled == 1) {
        return std::make_tuple(FusionTree.from_empty(symmetry), coupled, 0, coupled);
    }
    if (num_uncoupled == 2) {
        auto /* CHECKME: type? */ rest_tree = FusionTree.from_sector(symmetry, uncoupled[0], py::arg({keyword.key}) = val) /* CHECKME: keywords ['is_dual'] */;
        return std::make_tuple(rest_tree, coupled, multiplicities[0], uncoupled[-1]);
    }
    rest_tree = FusionTree(symmetry, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val, py::arg({keyword.key}) = val) /* CHECKME: keywords ['uncoupled', 'coupled', 'are_dual', 'inner_sectors', 'multiplicities'] */;
    return std::make_tuple(rest_tree, coupled, multiplicities[-1], uncoupled[-1]);
}

